package at.pinzker.taskloop;
import java.util.*;import java.util.regex.*;
public final class EnglishInput {
 public static String normalise(String value){String s=value;Matcher m=Pattern.compile("(?i)\\b(\\d{1,2})(?::(\\d{2}))?\\s*(am|pm)\\b").matcher(s);StringBuffer b=new StringBuffer();while(m.find()){int h=Integer.parseInt(m.group(1));if(h<1||h>12)continue;h=h%12+(m.group(3).equalsIgnoreCase("pm")?12:0);m.appendReplacement(b,""+h+":"+(m.group(2)==null?"00":m.group(2)));}m.appendTail(b);s=b.toString();String[][] map={{"day after tomorrow","übermorgen"},{"next occurrence","nächsten termin"},{"next day","nächsten tag"},{"tomorrow","morgen"},{"today","heute"},{"weekdays","werktags"},{"daily","täglich"},{"weekly","wöchentlich"},{"monthly","monatlich"},{"every day","jeden tag"},{"every week","jede woche"},{"every month","jeden monat"},{"monday","montag"},{"tuesday","dienstag"},{"wednesday","mittwoch"},{"thursday","donnerstag"},{"friday","freitag"},{"saturday","samstag"},{"sunday","sonntag"},{"remind again","erneut erinnern"},{"again","erneut"},{"minutes?","minuten"},{"hours?","stunden"},{"days?","tage"},{"weeks?","wochen"},{"months?","monate"},{"every","alle"},{"after","nach"},{"pause","pause"},{"at","um"}};for(String[] x:map)s=s.replaceAll("(?i)\\b(?:"+x[0]+")\\b",x[1]);s=s.replaceAll("(?i)\\bin\\s+(\\d+)\\s+tage\\b","in $1 tagen");return s;}
}
